#!/usr/bin/env bash
set -euo pipefail
cat > outcome-story.html <<'HTML'
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenEval Outcome Story</title><style>
:root{color-scheme:dark;font-family:ui-sans-serif,system-ui;background:#0a0d16;color:#f5f7ff}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 75% 10%,#273763,#0a0d16 60%)}main{width:min(900px,calc(100vw - 36px));padding:30px;border:1px solid #354367;border-radius:24px;background:#111a2c;box-shadow:0 24px 70px #0006}h1{margin:0;letter-spacing:-.04em}.lede{color:#aab7d6;line-height:1.5}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:24px}.metric{padding:14px;border:1px solid #2d3b5b;border-radius:12px;background:#16213a}.metric span{display:block;color:#aab7d6;font-size:12px}.metric strong{display:block;margin-top:8px;font-size:24px}.chart{margin-top:22px;padding:18px;border-radius:16px;background:#0c1425}.bars{display:grid;gap:10px}.row{display:grid;grid-template-columns:120px 1fr 70px;align-items:center;gap:12px;color:#c8d2e8;font-size:12px}.track{height:14px;border-radius:99px;background:#253553;overflow:hidden}.bar{height:100%;border-radius:inherit;background:linear-gradient(90deg,#64d8c8,#8c76ff)}.legend{margin-top:14px;color:#9ba9c6;font-size:12px}.legend::before{content:"";display:inline-block;width:9px;height:9px;border-radius:50%;background:#64d8c8;margin-right:6px} @media(max-width:640px){.metrics{grid-template-columns:repeat(2,1fr)}.row{grid-template-columns:92px 1fr 54px}}
</style></head><body><main data-testid="story-card"><h1>OpenEval Outcome Story</h1><p class="lede">The second half is faster, cheaper, and more trustworthy after the known-bad suite was added.</p><section class="metrics" aria-label="Outcome summary"><article class="metric" data-metric="pass-rate"><span>Pass rate</span><strong>50% → 80%</strong></article><article class="metric" data-metric="latency"><span>Median latency</span><strong>4.8s → 3.1s</strong></article><article class="metric" data-metric="cost"><span>API equivalent</span><strong>$0.42 / case</strong></article><article class="metric" data-metric="known-bad"><span>Known-bad rejection</span><strong>100%</strong></article></section><section class="chart" aria-labelledby="chart-title"><h2 id="chart-title">What changed</h2><div class="bars"><div class="row"><span>Pass rate</span><div class="track"><div class="bar" data-bar="pass-rate" style="width:80%"></div></div><strong>80%</strong></div><div class="row"><span>Speed retained</span><div class="track"><div class="bar" data-bar="speed" style="width:65%"></div></div><strong>65%</strong></div><div class="row"><span>Bad rejected</span><div class="track"><div class="bar" data-bar="known-bad" style="width:100%"></div></div><strong>100%</strong></div><div class="row"><span>Cost budget</span><div class="track"><div class="bar" data-bar="cost" style="width:42%"></div></div><strong>$0.42</strong></div></div><div class="legend">Bars are normalized to their own declared metric; lower latency is better.</div></section></main></body></html>
HTML
